  D_VAR(360) = RCT(789)*V(222)+RCT(791)*V(347)+RCT(800)*V(326)+RCT(802)*V(306)+RCT(810)*V(337)+RCT(815)*V(325)+RCT(846)&
                 &*V(258)+RCT(850)*V(301)+RCT(854)*V(292)
